static void side_load77(void){const int aw=2048,ah=512;unsigned char*out=calloc((size_t)aw*ah,4);if(!out)exit(21);for(int i=0;i<7;i++){const SideAsset77*a=sideAsset77+i;int w,h,c;unsigned char*p=stbi_load(a->file,&w,&h,&c,4);if(!p)exit(22);float aspect=(a->r-a->l)/(float)(a->b-a->t);int dw=504,dh=(int)(dw/aspect+.5f);if(dh>248){dh=248;dw=(int)(dh*aspect+.5f);}int tx=i%4*512+4,ty=i/4*256+4;sideUV77[i]=(Sprite){0,0,a->w,a->h,(tx+.5f)/aw,(ty+.5f)/ah,(dw-1.0f)/aw,(dh-1.0f)/ah};for(int y=0;y<dh;y++)for(int x=0;x<dw;x++){float sx=a->l+(x+.5f)*(a->r-a->l)/dw-.5f,sy=a->t+(y+.5f)*(a->b-a->t)/dh-.5f;int x0=clamp((int)floorf(sx),0,w-1),y0=clamp((int)floorf(sy),0,h-1);float fx=sx-floorf(sx),fy=sy-floorf(sy),alpha=0,rgb[3]={0};for(int q=0;q<4;q++){int xx=clamp(x0+(q&1),0,w-1),yy=clamp(y0+(q>>1),0,h-1);const unsigned char*sample=p+(yy*w+xx)*4;float weight=(q&1?fx:1-fx)*(q&2?fy:1-fy),aa=sample[3]/255.0f;alpha+=weight*aa;for(int k=0;k<3;k++)rgb[k]+=sample[k]*weight*aa;}unsigned char*d=out+((ty+y)*aw+tx+x)*4;for(int k=0;k<3;k++)d[k]=alpha>0?(unsigned char)clamp((int)(rgb[k]/alpha+.5f),0,255):0;d[3]=(unsigned char)clamp((int)(alpha*255+.5f),0,255);}stbi_image_free(p);}sideTexture77=SDL_CreateTexture(renderer,SDL_PIXELFORMAT_RGBA32,SDL_TEXTUREACCESS_STATIC,aw,ah);SDL_UpdateTexture(sideTexture77,NULL,out,aw*4);SDL_SetTextureBlendMode(sideTexture77,SDL_BLENDMODE_BLEND);SDL_SetTextureScaleMode(sideTexture77,SDL_SCALEMODE_LINEAR);strength_neutral_pixels(out,aw*ah);sideStrength77=SDL_CreateTexture(renderer,SDL_PIXELFORMAT_RGBA32,SDL_TEXTUREACCESS_STATIC,aw,ah);SDL_UpdateTexture(sideStrength77,NULL,out,aw*4);SDL_SetTextureBlendMode(sideStrength77,SDL_BLENDMODE_BLEND);SDL_SetTextureScaleMode(sideStrength77,SDL_SCALEMODE_LINEAR);sideDamage77=damage_mask(out,aw,ah);free(out);}
